package com.lolfm.composition;
import java.util.*;
public final class CompositionPatternPolicy{private static final Map<CompositionPattern,PatternDefinition>DEFINITIONS=build();private CompositionPatternPolicy(){}public static Map<CompositionPattern,PatternDefinition>definitions(){return DEFINITIONS;}private static Map<CompositionPattern,PatternDefinition>build(){EnumMap<CompositionPattern,PatternDefinition>m=new EnumMap<>(CompositionPattern.class);add(m,CompositionPattern.ENGAGE_CHAIN,ContributorRequirement.DISTINCT_PREFERRED,List.of(CompositionCapability.ENGAGE,CompositionCapability.FOLLOW_UP,CompositionCapability.BACKLINE_ACCESS),CompositionCapability.ENGAGE,CompositionCapability.FOLLOW_UP);add(m,CompositionPattern.FRONT_TO_BACK,ContributorRequirement.DISTINCT_REQUIRED,List.of(CompositionCapability.FRONTLINE,CompositionCapability.PEEL,CompositionCapability.SUSTAINED_DAMAGE),CompositionCapability.FRONTLINE,CompositionCapability.SUSTAINED_DAMAGE);add(m,CompositionPattern.POKE_SIEGE,ContributorRequirement.ANY,List.of(CompositionCapability.POKE,CompositionCapability.SIEGE,CompositionCapability.WAVE_CLEAR));add(m,CompositionPattern.PICK_CONVERSION,ContributorRequirement.DISTINCT_PREFERRED,List.of(CompositionCapability.PICK,CompositionCapability.BURST_DAMAGE,CompositionCapability.OBJECTIVE_DAMAGE),CompositionCapability.PICK,CompositionCapability.OBJECTIVE_DAMAGE);add(m,CompositionPattern.SPLIT_MAP_PRESSURE,ContributorRequirement.DISTINCT_REQUIRED,List.of(CompositionCapability.SIDE_LANE_PRESSURE,CompositionCapability.WAVE_CLEAR,CompositionCapability.DISENGAGE),CompositionCapability.SIDE_LANE_PRESSURE,CompositionCapability.WAVE_CLEAR);add(m,CompositionPattern.OBJECTIVE_CONTROL,ContributorRequirement.DISTINCT_PREFERRED,List.of(CompositionCapability.OBJECTIVE_DAMAGE,CompositionCapability.ZONE_CONTROL,CompositionCapability.FRONTLINE),CompositionCapability.OBJECTIVE_DAMAGE,CompositionCapability.FRONTLINE);return Map.copyOf(m);}private static void add(Map<CompositionPattern,PatternDefinition>m,CompositionPattern p,ContributorRequirement r,List<CompositionCapability>c,CompositionCapability...d){m.put(p,new PatternDefinition(p,c,r,List.of(d),"composition.pattern."+p.name().toLowerCase()));}}
